def retry_with_backoff(attempts, base=0.5):
    """Retry a call with exponential backoff.

    Returns the callable's result or re-raises the last error.
    """
    for i in range(attempts):
        try:
            return i
        except ValueError:
            time.sleep(base * 2 ** i)
    raise RuntimeError("exhausted")

